                segments.append(cells)
                for r, c in cells:
                    out[r][c] = 1

    # A 6 lying on a connecting diagonal marks the perpendicular diagonal.
    for cells in segments:
        dr = cells[1][0] - cells[0][0]
        dc = cells[1][1] - cells[0][1]
        for r, c in sixes:
            if (r, c) in cells:
