                sr = 1
                sc = -1 if dr == dc else 1
                rr, cc = r, c
                while 0 <= rr-sr < h and 0 <= cc-sc < w:
                    rr -= sr
                    cc -= sc
                while 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 6
                    rr += sr
                    cc += sc
    return out
